def load_prices(days=2000):
    """Return dict {symbol: df} of daily OHLCV via API (capped at current date)."""
    out = {}
    for s in WATCHLIST:
        try:
            df = get_stock_daily_data(symbol=s, days=days)
            if df is not None and len(df) >= 30:
                df = df.copy()
